<script setup lang="ts">
import { ref,onMounted,onUnmounted,computed } from 'vue'
import Gateway from './Gateway.vue'
import { api,post,user,bytes } from '../api'
const props=defineProps<{section:string}>()
const rebootAuth=ref(false),rebootPassword=ref(''),rebootCode=ref('')
const sort=ref('cpu'),ports=ref<any[]>([]),blocks=ref<any[]>([]),auditUser=ref(''),auditAction=ref(''),auditResult=ref(''),logQuery=ref(''),logSite=ref(false),logKind=ref('access')
const rows=ref<any[]>([]),host=ref<Record<string,any>>({}),settings=ref<Record<string,string>>({}),security=ref<Record<string,any>>({}),error=ref(''),success=ref(''),busy=ref(false),offset=ref(0),search=ref(''),form=ref<Record<string,any>|null>(null),editing=ref(false),firewall=ref(''),logs=ref<string[]>([]),audit=ref<any[]>([]),runs=ref<any[]>([]),logTitle=ref(''),totpPassword=ref(''),totpCode=ref(''),totpSecret=ref('')
let source:EventSource|undefined
const isAdmin=computed(()=>user.value?.role==='admin'),editable=computed(()=>user.value?.role!=='viewer')
interface Field {key:string;label:string;required?:boolean;type?:string;options?:string[]}
const fields=computed<Field[]>(()=>{
 switch(props.section){
 case 'sites':return [{key:'name',label:'站点名称',required:true},{key:'domains',label:'域名（逗号分隔）',required:true},{key:'kind',label:'站点类型',options:['static','proxy']},{key:'root',label:'静态目录（/var/www/ 下）'},{key:'upstream',label:'代理上游地址'},{key:'notFound',label:'自定义 404 URI（如 /404.html）'},{key:'enabled',label:'启用网站',type:'checkbox'},{key:'https',label:'启用 HTTPS（请先申请或导入证书）',type:'checkbox'},{key:'redirect',label:'HTTP 跳转 HTTPS',type:'checkbox'}]
 case 'tasks':return [{key:'name',label:'任务名称',required:true},{key:'schedule',label:'Cron 表达式（分 时 日 月 周）',required:true},{key:'command',label:'执行命令',type:'textarea',required:true},{key:'account',label:'执行账号（非 root）',required:true},{key:'workdir',label:'工作目录（绝对路径，空为账号主目录）'},{key:'timeout',label:'超时时间（秒，1–900）',type:'number'},{key:'enabled',label:'启用调度',type:'checkbox'}]
 case 'users':return [{key:'Name',label:'用户名',required:true},{key:'Password',label:'密码（12–72 字节；编辑时留空保留）',type:'password'},{key:'Role',label:'角色',options:['admin','operator','viewer']},{key:'Disabled',label:'禁用账户',type:'checkbox'},{key:'Terminal',label:'单独授权 Web SSH（运维成员）',type:'checkbox'}]
 case 'certificates':return [{key:'Name',label:'对应站点名称',required:true},{key:'Action',label:'操作',options:['issue','import']},{key:'Email',label:'ACME 联系邮箱'},{key:'Agree',label:'同意 Let’s Encrypt 订阅协议（申请证书时必须）',type:'checkbox'},{key:'Certificate',label:'PEM 证书链（导入时填写）',type:'textarea'},{key:'PrivateKey',label:'PEM 私钥（导入时填写）',type:'textarea'}]
 default:return []
 }
})
const serviceRows=computed(()=>rows.value.filter(r=>!search.value||r.name.includes(search.value)))
const settingFields=[['panel.name','面板名称'],['smtp.host','SMTP 主机'],['smtp.port','SMTP 端口（STARTTLS）'],['smtp.user','SMTP 用户名'],['smtp.password','SMTP 密码'],['smtp.from','发件邮箱'],['smtp.to','收件邮箱'],['alerts.cpu','CPU 告警阈值 %'],['alerts.memory','内存告警阈值 %'],['alerts.disk','磁盘告警阈值 %'],['alerts.load','负载告警阈值（默认 CPU 核数 ×2）'],['alerts.services','监控服务（逗号分隔，最多 20 个）'],['alerts.quiet.start','通知静默开始（HH:mm）'],['alerts.quiet.end','通知静默结束（HH:mm）'],['security.allowIPs','面板 IP 白名单（IP/CIDR，逗号分隔；空表示不限）'],['session.idleMinutes','会话空闲分钟（5–240）'],['session.maxHours','会话最长小时（1–24）'],['files.root','文件根目录（服务器绝对路径）'],['uploads.maxMB','单文件上传上限 MB（1–100）'],['retention.auditDays','审计保留天数（1–365）'],['retention.taskDays','任务记录保留天数（1–90）']]
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';success.value='';try{await fn();success.value='操作完成'}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){error.value='';try{const section=props.section
 if(section==='host'){host.value=await api('host');rows.value=await api(`processes?sort=${sort.value}&offset=${offset.value}&q=${encodeURIComponent(search.value)}`);try{ports.value=await api('ports')}catch(e){error.value=String(e)}}
 else if(section==='settings'){settings.value=await api('settings');if(settings.value['smtp.password']==='[configured]')delete settings.value['smtp.password']}
 else if(section==='security'){security.value=await api('security');audit.value=await api('audit?user='+encodeURIComponent(auditUser.value)+'&action='+encodeURIComponent(auditAction.value)+'&result='+encodeURIComponent(auditResult.value));blocks.value=await api('login-blocks');try{firewall.value=(await api('firewall')).output}catch(e){firewall.value=String(e)}}
 else if(section==='services'){const data=await api('services?offset='+offset.value+'&q='+encodeURIComponent(search.value));rows.value=data.items}
 else if(section==='tasks'){rows.value=await api(`tasks?offset=${offset.value}`);runs.value=await api('runs')}
 else rows.value=await api(`${section}?offset=${offset.value}`)
 }catch(e){error.value=String(e)}}
function create(row?:any){editing.value=!!row
 if(props.section==='sites')form.value=row?{...row,domains:row.domains.join(', ')}:{name:'',domains:'',kind:'static',root:'/var/www/',upstream:'',notFound:'',enabled:true,https:false,redirect:false}
 else if(props.section==='tasks')form.value=row?{...row.task}:{name:'',schedule:'0 2 * * *',command:'',account:'www-data',workdir:'',timeout:300,enabled:false}
 else if(props.section==='users')form.value=row?{ID:row.id,Name:row.name,Role:row.role,Disabled:row.disabled,Terminal:row.terminal,Password:'',Action:'save'}:{Name:'',Password:'',Role:'operator',Disabled:false,Terminal:false,Action:'save'}
 else form.value={Name:row?.name||'',Action:'issue',Email:'',Agree:false,Certificate:'',PrivateKey:''}
}
async function save(){await perform(async()=>{const data={...form.value};if(props.section==='sites')data.domains=data.domains.split(',').map((s:string)=>s.trim().toLowerCase()).filter(Boolean);await post(props.section,data);form.value=null;await load()})}
async function acknowledge(id:number){await perform(async()=>{await post('alerts',{ID:id});await load()})}
async function unblock(ip:string){await perform(async()=>{await post('login-blocks',{IP:ip});await load()})}
async function deleteCertificate(name:string){if(!confirm('确定删除证书？请先停用网站的 HTTPS。'))return;await perform(async()=>{await api('certificates',{method:'DELETE',body:JSON.stringify({Name:name})});await load()})}
async function checkDomain(domain:string){await perform(async()=>{const result=await api('domains/check?domain='+encodeURIComponent(domain));alert(domain+' → '+result.addresses.join(', ')+'；请确认解析到本机公网地址。')})}
async function remove(row:any){if(!confirm('确定删除？网站文件和证书将保留，其他删除操作不可恢复。'))return;await perform(async()=>{if(props.section==='users')await post('users',{ID:row.id,Name:row.name,Role:row.role,Disabled:row.disabled,Password:'',Action:'delete'});else await api(props.section,{method:'DELETE',body:JSON.stringify(row.task||row)});await load()})}
async function service(name:string,action:string){if(!confirm(`对 ${name} 执行 ${action}？`))return;await perform(async()=>{await post('services',{Name:name,Action:action});await load()})}
async function fullRun(event:Event,run:any){if(!(event.target as HTMLDetailsElement).open)return;try{const result=await api('run?id='+run.id);run.output=result.output}catch(e){error.value=String(e)}}
async function runTask(row:any){if(!confirm(`立即执行任务 ${row.task.name}？`))return;await perform(async()=>{await post('tasks',{id:row.task.id,action:'run'});await load()})}
async function terminate(pid:number){if(!confirm(`向进程 ${pid} 发送 SIGTERM？`))return;await perform(async()=>{await post('processes',{PID:pid});await load()})}
function reboot(){rebootAuth.value=true}
async function confirmReboot(){await perform(async()=>{await post('reboot',{Password:rebootPassword.value,Code:rebootCode.value,Confirm:true});rebootAuth.value=false});rebootPassword.value='';rebootCode.value=''}
function showLogs(unit:string,site=false){source?.close();logs.value=[];logTitle.value=unit;logSite.value=site;source=new EventSource('/api/logs?'+(site?'site=':'unit=')+encodeURIComponent(unit)+'&q='+encodeURIComponent(logQuery.value)+'&kind='+logKind.value);source.onmessage=e=>{logs.value.push(JSON.parse(e.data));if(logs.value.length>1000)logs.value.splice(0,logs.value.length-1000)};source.onerror=()=>{source?.close();logs.value.push('[日志流已断开，可关闭后重新打开]')}}
function closeLogs(){source?.close();source=undefined;logTitle.value=''}
async function saveSettings(){await perform(async()=>{const clean=Object.fromEntries(Object.entries(settings.value).filter(([k,v])=>(settingFields.some(([key])=>key===k)||k==='alerts.enabled')&&(v!==''||['security.allowIPs','alerts.services','alerts.quiet.start','alerts.quiet.end','smtp.user'].includes(k))));await post('settings',clean)})}
async function fw(action:string){const data:Record<string,any>={Action:action,Confirm:true};if(['allow','deny','delete'].includes(action)){const port=prompt('端口（1–65535）');if(!port)return;data.Port=Number(port);data.Protocol=prompt('协议：tcp 或 udp','tcp');data.Source=prompt('来源 IP/CIDR，或 any','any');if(action==='delete')data.Policy=prompt('原规则策略：allow 或 deny','allow')};if(action!=='confirm'&&!confirm('变更可能影响访问。必须在 60 秒内点击“确认连接正常”，否则自动恢复。'))return;await perform(async()=>{await post('firewall',data);await load()})}
async function totp(action:string){await perform(async()=>{const r=await post('security/totp',{Action:action,Password:totpPassword.value,Code:totpCode.value,Secret:''});if(action==='prepare')totpSecret.value=r.secret;else{user.value=null;totpPassword.value='';totpCode.value='';totpSecret.value=''}})}
onMounted(load);onUnmounted(closeLogs)
</script>
<template>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>
 <div class="toolbar"><input v-if="['host','services'].includes(section)" v-model="search" placeholder="搜索名称或 PID" @change="offset=0;load()"><button :disabled="busy" @click="load">↻ 刷新</button><button v-if="editable&&['sites','tasks','users','certificates'].includes(section)" class="primary" @click="create()">＋ {{section==='certificates'?'申请 / 导入证书':'新建'}}</button></div>
 <section v-if="section==='host'" class="card"><h2>本机信息</h2><dl class="details"><template v-for="(value,key) in host" :key="key"><dt>{{key}}</dt><dd class="wrap">{{value}}</dd></template></dl><div class="section-head"><h2>进程列表</h2><div><button @click="sort='cpu';load()">按 CPU</button> <button @click="sort='memory';load()">按内存</button> <button v-if="isAdmin" class="danger" @click="reboot">重启服务器</button></div></div><div class="table-wrap"><table><thead><tr><th>PID</th><th>进程名称</th><th>CPU</th><th>内存</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.pid"><td>{{p.pid}}</td><td>{{p.name}}</td><td>{{p.cpu.toFixed(1)}}%</td><td>{{bytes(p.memory)}}</td><td><button v-if="isAdmin" class="quiet danger" @click="terminate(p.pid)">终止</button></td></tr></tbody></table></div><h2 style="margin-top:24px">监听端口（缓存 60 秒）</h2><div class="table-wrap"><table><thead><tr><th>地址</th><th>端口</th><th>协议</th><th>PID / 进程</th></tr></thead><tbody><tr v-for="p in ports" :key="p.protocol+p.address+p.port"><td>{{p.address}}</td><td>{{p.port}}</td><td>{{p.protocol}}</td><td>{{p.pid||'—'}} / {{p.process||'未知'}}</td></tr></tbody></table></div></section>
 <section v-else-if="section==='sites'" class="card table-wrap"><table><thead><tr><th>网站</th><th>域名</th><th>类型 / 目标</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td><strong>{{s.name}}</strong></td><td><div v-for="d in s.domains" :key="d">{{d}} <button class="quiet" @click="checkDomain(d)">检查解析</button></div></td><td>{{s.kind==='static'?'静态网站':'反向代理'}}<small class="block muted">{{s.kind==='static'?s.root:s.upstream}}</small></td><td><span :class="['badge',s.enabled?'success':'']">{{s.enabled?'已启用':'已停用'}}</span><small class="block muted">{{s.https?'HTTPS':'HTTP'}}</small></td><td><button class="quiet" @click="showLogs(s.name,true)">日志</button><button v-if="editable" class="quiet" @click="create(s)">编辑</button><button v-if="editable" class="quiet danger" @click="remove(s)">删除</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">暂无网站。创建静态站点或反向代理开始使用。</p></section>
 <section v-else-if="section==='certificates'" class="card table-wrap"><div class="notice">证书以站点名称绑定。签发前，站点必须启用、域名解析正确且公网 80 端口可达；签发后编辑网站开启 HTTPS。</div><table><thead><tr><th>站点</th><th>域名</th><th>签发机构</th><th>到期时间</th><th>续期</th></tr></thead><tbody><tr v-for="c in rows" :key="c.name"><td>{{c.name}}</td><td>{{c.domains.join(', ')}}</td><td>{{c.issuer}}</td><td>{{new Date(c.expires).toLocaleString()}}</td><td>{{c.automatic?'自动':'手动导入'}} <button class="quiet" @click="create(c)">更新</button><button class="quiet danger" @click="deleteCertificate(c.name)">删除</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">暂无证书</p></section>
 <section v-else-if="section==='services'" class="card table-wrap"><table><thead><tr><th>服务</th><th>状态</th><th>开机启动</th><th>描述</th><th>操作</th></tr></thead><tbody><tr v-for="s in serviceRows" :key="s.name"><td>{{s.name}}</td><td><span :class="['badge',s.state==='active'?'success':'']">{{s.state}} / {{s.sub}}</span></td><td>{{s.startup}}</td><td>{{s.description}}</td><td><button class="quiet" @click="showLogs(s.name)">日志</button><template v-if="editable"><button v-for="[action,label] in [['start','启动'],['stop','停止'],['restart','重启'],['enable','开机启动'],['disable','取消自启']]" :key="action" class="quiet" :disabled="busy" @click="service(s.name,action)">{{label}}</button></template></td></tr></tbody></table></section>
 <template v-else-if="section==='tasks'"><section class="card table-wrap"><div class="notice">使用服务器时区调度，不补跑停机期间任务；执行账号不能是 root。队列最多 32 个任务。</div><table><thead><tr><th>任务</th><th>周期</th><th>下一次执行</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.task.id"><td>{{r.task.name}}<small class="block muted">{{r.task.account}}</small></td><td><code>{{r.task.schedule}}</code></td><td>{{r.next[0]||'—'}}</td><td>{{r.task.enabled?'已启用':'已停用'}}</td><td><button class="quiet" @click="runTask(r)">执行</button><button class="quiet" @click="create(r)">编辑</button><button class="quiet danger" @click="remove(r)">删除</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">暂无定时任务</p></section><section class="card"><h2>最近执行记录</h2><details v-for="r in runs" :key="r.id" class="run" @toggle="fullRun($event,r)"><summary>任务 #{{r.task_id}} · {{r.status}} · 退出码 {{r.exit_code??'—'}} · {{new Date(r.started*1000).toLocaleString()}}</summary><pre>{{r.output||'无输出'}}</pre></details></section></template>
 <section v-else-if="section==='users'" class="card table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>双因素认证</th><th>操作</th></tr></thead><tbody><tr v-for="u in rows" :key="u.id"><td>{{u.name}}</td><td>{{u.role}}</td><td>{{u.disabled?'已禁用':'正常'}}</td><td>{{u.totp?'已启用':'未启用'}}</td><td><button class="quiet" @click="create(u)">编辑</button><button class="quiet danger" :disabled="u.id===user?.id" @click="remove(u)">删除</button></td></tr></tbody></table></section>
 <section v-else-if="section==='settings'" class="card"><h2>基础设置与邮件通知</h2><form class="form-grid" @submit.prevent="saveSettings"><label v-for="[key,label] in settingFields" :key="key">{{label}}<input v-model="settings[key]" :type="key==='smtp.password'?'password':'text'" :placeholder="key==='smtp.password'?'留空保留现有密码':''"></label><label class="check"><input v-model="settings['alerts.enabled']" type="checkbox" true-value="true" false-value="false">启用资源告警</label><div class="form-actions"><button class="primary" :disabled="busy">保存设置</button><button type="button" @click="perform(async()=>{await post('mail/test',{})})">发送测试邮件</button></div></form><div class="notice">监控保留：实时 1 小时、分钟聚合 7 天、小时聚合 30 天；审计 180 天、任务输出 30 天。运行参数由 systemd 服务配置控制。</div></section>
 <template v-else-if="section==='security'"><div class="dashboard-grid"><section class="card"><div class="section-head"><h2>基础安全状态</h2><a href="/api/diagnostics">导出诊断</a></div><dl class="details"><dt>HTTPS</dt><dd>{{security.https?'已启用':'当前连接未加密'}}</dd><dt>终端访问</dt><dd>管理员及单独授权的运维成员</dd><dt>登录保护</dt><dd>5 次失败后封禁 15 分钟</dd><dt>会话策略</dt><dd>空闲 30 分钟 / 最长 12 小时</dd></dl><h2>登录封禁</h2><div v-for="b in blocks" :key="b.ip" class="list-row">{{b.ip}} <button class="quiet" @click="unblock(b.ip)">解除封禁</button></div><h2>双因素认证</h2><label>当前密码<input v-model="totpPassword" type="password"></label><label>验证码<input v-model="totpCode" inputmode="numeric" maxlength="6"></label><div class="toolbar"><button @click="totp('prepare')">生成密钥</button><button class="primary" @click="totp('enable')">确认启用</button><button @click="totp('disable')">停用</button></div><p v-if="totpSecret" class="notice wrap">请在认证器中手动添加此密钥：<code>{{totpSecret}}</code>，5 分钟内输入验证码完成启用。</p></section><section class="card"><h2>UFW 防火墙</h2><pre>{{firewall}}</pre><div class="toolbar wrap"><button @click="fw('enable')">启用</button><button @click="fw('disable')">停用</button><button @click="fw('allow')">允许规则</button><button @click="fw('deny')">拒绝规则</button><button @click="fw('delete')">删除规则</button><button class="primary" @click="fw('confirm')">确认连接正常</button></div><p class="muted small">规则变更后 60 秒未确认将自动恢复。已有其他防火墙管理器时拒绝接管。</p></section></div><section class="card table-wrap"><h2>操作审计</h2><div class="toolbar"><input v-model="auditUser" placeholder="按用户筛选"><input v-model="auditAction" placeholder="按操作筛选"><input v-model="auditResult" placeholder="按结果筛选"><button @click="load">筛选</button></div><table><thead><tr><th>时间</th><th>用户</th><th>操作</th><th>目标</th><th>结果</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{new Date(a.time*1000).toLocaleString()}}</td><td>{{a.user}}</td><td>{{a.action}}</td><td>{{a.target}}</td><td>{{a.result}}</td></tr></tbody></table></section></template>
 <section v-else-if="section==='alerts'" class="card"><div class="notice">CPU、内存、磁盘默认持续 5 分钟触发告警，持续异常每 30 分钟提醒，恢复后通知。阈值与邮件渠道由管理员在系统设置中配置。</div><div v-for="a in rows" :key="a.id" class="list-row"><span :class="['badge',a.active?'warning':'success']">{{a.active?'告警中':'已恢复'}}</span><strong>{{a.message}}</strong><time class="muted">{{new Date(a.updated*1000).toLocaleString()}}</time><button v-if="editable&&!a.ack_at" class="quiet" @click="acknowledge(a.id)">确认</button><small v-if="a.ack_at" class="muted">{{a.ack_by}} 已确认</small></div><p v-if="!rows.length" class="empty">暂无告警</p></section>
 <div v-if="['sites','tasks','users','alerts','host','services'].includes(section)" class="pagination"><button :disabled="offset===0" @click="offset=Math.max(0,offset-50);load()">上一页</button><span>第 {{offset/50+1}} 页</span><button :disabled="rows.length<50" @click="offset+=50;load()">下一页</button></div>
 <div v-if="rebootAuth" class="modal-backdrop"><section class="card modal"><h2>确认重启服务器</h2><p class="notice">重启将中断所有连接和业务进程。完成身份验证后 5 秒执行。</p><form @submit.prevent="confirmReboot"><label>管理员密码<input v-model="rebootPassword" type="password" autocomplete="current-password" required></label><label>双因素验证码（如已启用）<input v-model="rebootCode" inputmode="numeric" maxlength="6"></label><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">确认重启</button><button type="button" @click="rebootAuth=false;rebootPassword='';rebootCode=''">取消</button></form></section></div>
 <Gateway v-if="section==='settings'"/>
 <div v-if="form" class="modal-backdrop"><section class="card modal" role="dialog" aria-modal="true"><div class="section-head"><h2>{{editing?'编辑':'新建'}}{{section==='sites'?'网站':section==='tasks'?'定时任务':section==='users'?'用户':'证书'}}</h2><button @click="form=null">关闭</button></div><form @submit.prevent="save"><label v-for="field in fields" :key="field.key" :class="{check:field.type==='checkbox'}"><template v-if="field.type==='checkbox'"><input v-model="form[field.key]" type="checkbox">{{field.label}}</template><template v-else>{{field.label}}<select v-if="field.options" v-model="form[field.key]"><option v-for="o in field.options" :key="o">{{o}}</option></select><textarea v-else-if="field.type==='textarea'" v-model="form[field.key]" rows="4" :required="field.required"></textarea><input v-else v-model="form[field.key]" :type="field.type||'text'" :required="field.required" :disabled="editing&&['name','Name'].includes(field.key)"></template></label><p v-if="section==='certificates'" class="small"><a href="https://letsencrypt.org/repository/" target="_blank" rel="noreferrer">查看 Let’s Encrypt 订阅协议</a></p><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'处理中…':'保存并应用'}}</button></form></section></div>
 <div v-if="logTitle" class="modal-backdrop"><section class="card modal log-modal"><div class="section-head"><h2>{{logTitle}} 日志</h2><button @click="closeLogs">关闭</button></div><div class="toolbar"><input v-model="logQuery" placeholder="日志关键词"><select v-if="logSite" v-model="logKind"><option value="access">访问日志</option><option value="error">错误日志</option></select><button @click="showLogs(logTitle,logSite)">重新过滤</button></div><pre>{{logs.join('\n')||'等待日志…'}}</pre><p class="muted small">最多保留 1,000 行；30 分钟后断开。</p></section></div>
</template>
